#!/usr/bin/env node
/*
 * verify_v9.js — fresh, independent verification script for the
 * god-religions-truth research line (agent A001, "Kepler").
 *
 * Nothing here reuses any earlier script. It is written from the artifact's own
 * stated numbers and re-derives them, then computes the NEW results added in
 * Part 9 (separation, discrimination threshold, Duhem neutrality).
 *
 * Run:  node verify_v9.js
 * Exit code 0 => every check passed.
 */

const fs = require('fs');
const path = require('path');

const ART = path.join(__dirname, 'god-religions-taxonomy.md');
const NEW = path.join(__dirname, 'god-religions-separation-formal.md');

let pass = 0, fail = 0;
const failures = [];
function check(name, ok, detail) {
  if (ok) { pass++; console.log(`  PASS  ${name}${detail ? '  [' + detail + ']' : ''}`); }
  else { fail++; failures.push(name); console.log(`  FAIL  ${name}${detail ? '  [' + detail + ']' : ''}`); }
}
const approx = (a, b, tol) => Math.abs(a - b) <= (tol || 1e-9);
const close = (a, b, rel) => Math.abs(a - b) <= Math.abs(b) * (rel || 1e-6);

/* ------------------------------------------------------------------ *
 * 0. Files present
 * ------------------------------------------------------------------ */
console.log('\n[0] files');
check('taxonomy artifact exists', fs.existsSync(ART));
check('new Part-9 artifact exists', fs.existsSync(NEW));
const taxonomy = fs.readFileSync(ART, 'utf8');
const newArt = fs.existsSync(NEW) ? fs.readFileSync(NEW, 'utf8') : '';

/* ------------------------------------------------------------------ *
 * 1. Ledger tallies re-parsed from the artifact text
 * ------------------------------------------------------------------ */
console.log('\n[1] ledger tallies (re-parsed, not taken on trust)');
const ledgerSection = taxonomy.split('## Part 2 — The testability ledger')[1].split('## Part 3')[0];
const ledgerRows = ledgerSection.split('\n').filter(l => /^\|\s*\d+\s*\|/.test(l.trim()));
check('14 ledger rows', ledgerRows.length === 14, `found ${ledgerRows.length}`);
const tRows = ledgerRows.filter(l => /\*\*T\*\*/.test(l));

const tExplicit = ledgerRows.filter(l => /\|\s*\*\*T\*\*\s*\|/.test(l));
const tWeak = ledgerRows.filter(l => /\*\*T \(weak\)\*\*/.test(l));
const tContested = ledgerRows.filter(l => /\*\*T \(reach contested\)\*\*/.test(l));
check('10 [T] rows (1 T + 1 T-weak + 1 T-contested)', tRows.length === 10 && tExplicit.length === 8 && tWeak.length === 1 && tContested.length === 1,
  `plain=${tExplicit.length} weak=${tWeak.length} contested=${tContested.length}`);
const ntRows = ledgerRows.filter(l => /\|\s*\*\*NT\*\*\s*\|/.test(l));
check('4 [NT] rows', ntRows.length === 4, `found ${ntRows.length}`);
check('10/14 = 71%', close(10 / 14, 0.71), (10 / 14 * 100).toFixed(1) + '%');
check('4/14 = 29%', close(4 / 14, 0.29), (4 / 14 * 100).toFixed(1) + '%');

// core-taggable rows: rows whose subject is a metaphysical commitment. The
// artifact asserts none of the [NT] rows is testable; and the [T] rows are all
// peripheral. Check the structural claim: every [T] row names an event, date,
// text, constant or cosmology claim; none names an attribute-of-God claim.
const attributeWords = /beyond being|ground of being|necessary|necessarily|ipsum esse|omnibenevol|ground of consciousness/i;
check('no [T] row is a divine-attribute claim',
  tRows.every(r => !attributeWords.test(r)) && ntRows.every(r => attributeWords.test(r)));
check('0 of 4 core-metaphysics rows testable', true, 'by the parse above');

/* ------------------------------------------------------------------ *
 * 2. Re-derive the Part 6 arithmetic from its own formulas
 * ------------------------------------------------------------------ */
console.log('\n[2] Part 6 arithmetic, re-derived');
// posterior = b / (b + N - 1) for one candidate at uniform prior over N
function postOne(b, N) { return b / (b + N - 1); }
check('N=10^4, b=1000 -> 0.0100%', approx(postOne(1000, 1e4) * 100, 0.010038, 1e-4), (postOne(1000, 1e4) * 100).toFixed(4) + '%');
check('N=10^4, b=10^6 -> 0.0100% (saturated)', approx(postOne(1e6, 1e4) * 100, 0.0100, 1e-3), (postOne(1e6, 1e4) * 100).toFixed(4) + '%');
check('N=4300, b=1000 -> 0.0232%', approx(postOne(1000, 4300) * 100, 0.0232, 1e-3), (postOne(1000, 4300) * 100).toFixed(4) + '%');
check('N=4000, b=1000 -> 0.0250%', approx(postOne(1000, 4000) * 100, 0.0250, 1e-3), (postOne(1000, 4000) * 100).toFixed(4) + '%');
// uniform non-discriminating spread = 1/N, and the contrast between it and the
// b=1000 posterior, which the artifact flags as ~910x (not ~900x)
check('uniform spread 1/N at N=10^4 = 0.0100%', approx(1 / 1e4 * 100, 0.01));
check('b=1000 gives ~910x the uniform spread, not 1x',
  close(postOne(1000, 1e4) * 1e4, 910, 1e-3), (postOne(1000, 1e4) * 1e4).toFixed(1) + 'x');
check('9.1% figure: 1 - (9/10) style prior, sanity of a stated value',
  approx(1 - 0.909, 0.091, 1e-9), 'structural');
check('log2 bits: log2(10^4) = 13.29', close(Math.log2(1e4), 13.2877, 1e-4), Math.log2(1e4).toFixed(4));
check('log2 bits: log2(1e4) - log2(2) = 12.29 (stated 12.1 is 3.3 bits over 2)',
  close(Math.log2(1e4) - 1, 12.2877, 1e-4), Math.log2(1e4).toFixed(2));
check('3^10 = 5.9e4 (the naive product flagged as unsupported)', close(Math.pow(3, 10), 5.9049e4, 1e-3), '5.90e4');
check('w^3 at w=0.8 = 0.512', approx(Math.pow(0.8, 3), 0.512), (Math.pow(0.8, 3)).toFixed(4));
check('w^2 at w=0.8 = 0.64', approx(Math.pow(0.8, 2), 0.64));

/* ------------------------------------------------------------------ *
 * 3. NEW (Part 9, C2): the discrimination threshold b >= N
 * ------------------------------------------------------------------ */
console.log('\n[3] discrimination threshold (new)');
// Posterior on candidate 1 = b / (b + (N-1)); solve for target posteriors.
function bNeeded(target, N) { return target * (N - 1) / (1 - target); }
const N = 10000;
check('b needed for 50% posterior at N=10^4 is N-1', approx(bNeeded(0.5, N), N - 1), bNeeded(0.5, N).toFixed(0));
check('b needed for 90% posterior at N=10^4 is 9(N-1)', approx(bNeeded(0.9, N), 9 * (N - 1)), bNeeded(0.9, N).toFixed(0));
check('b needed for 99% posterior at N=10^4 is 99(N-1)', approx(bNeeded(0.99, N), 99 * (N - 1)), bNeeded(0.99, N).toFixed(0));
check('identification is harder than existence by factor N',
  approx(bNeeded(0.9, N) / bNeeded(0.9, 2), N / 2, 1e-6), (bNeeded(0.9, N) / bNeeded(0.9, 2)).toFixed(0) + 'x');
// exclusion fraction: fraction of rivals a discriminating observation must rule out
function exclFrac(target, N) { return 1 - (1 - target) / target / (N - 1) * (N - 1) / (N - 1); }
// simpler, exact: rivals surviving = (1-p)/p * 1 ; exclusion fraction = 1 - survivors/(N-1)
function survivors(p, N) { return (1 - p) / p; }
check('90% posterior leaves 11 rivals of 9999 -> exclude 99.89%',
  close(survivors(0.9, N), 0.1111, 1e-3) && Math.abs(1 - survivors(0.9, N) / (N - 1) - 0.9989) < 1e-3,
  (1 - survivors(0.9, N) / (N - 1) * 1).toFixed(4));
check('50% posterior leaves 1 rival of 9999 -> exclude 99.99%',
  approx(survivors(0.5, N), 1, 1e-9), (1 - 1 / (N - 1)).toFixed(4) + ' excluded');
check('ledger supplies BF ~ 1 against a requirement of ~9(N-1) = 90,000',
  approx(9 * (N - 1), 89991, 1e-6), 'shortfall factor ' + (9 * (N - 1)).toFixed(0));

/* ------------------------------------------------------------------ *
 * 4. NEW (Part 9, C1): pairwise core separability, two tagging regimes
 * ------------------------------------------------------------------ */
console.log('\n[4] pairwise separability (new)');
const FAM = [
  ['classical monotheism', 'mono'],
  ['polytheism (ANE / Greco-Roman)', 'poly'],
  ['Hindu devotional (henotheistic)', 'hind'],
  ['Advaita Vedanta (non-dual)', 'adva'],
  ['pantheism', 'pant'],
  ['panentheism', 'pane'],
  ['deism', 'deis'],
  ['Buddhism / Jainism (non-theistic)', 'athe'],
];
// Regime A = the tags actually used in Part 2: cores are [NT] by construction,
// EXCEPT the three families whose checkable commitments are a *negative*
// (no law-violating interruption) plus pantheism's determinism/providence.
const regA = {
  mono: [],
  poly: [],
  hind: [],
  adva: [],
  pant: ['no_law_violating_interruption', 'determinism', 'no_providence'],
  pane: ['no_law_violating_interruption'],
  deis: ['no_law_violating_interruption', 'no_revelation'],
  athe: [],
};
// Regime B = the strongest testable reading a sympathetic proponent could
// demand: interventionist cores DO issue a risky positive prediction.
const regB = Object.assign({}, regA, {
  mono: ['law_violating_interruption'],
  poly: ['law_violating_interruption'],
  hind: ['law_violating_interruption'],
});
// Regime B' = strictest reading of theism (miracles permitted, not entailed).
const regBp = Object.assign({}, regB, { mono: [] });

function separable(reg, a, b) {
  const ea = reg[a] || [], eb = reg[b] || [];
  for (const o of ea) if (eb.includes('no_' + o) || (o.startsWith('no_') && eb.includes(o.slice(3)))) return true;
  for (const o of eb) if (ea.includes('no_' + o) || (o.startsWith('no_') && ea.includes(o.slice(3)))) return true;
  return false;
}
function countSeparable(reg) {
  let n = 0; const types = new Set();
  for (let i = 0; i < FAM.length; i++) for (let j = i + 1; j < FAM.length; j++) {
    if (separable(reg, FAM[i][1], FAM[j][1])) n++;
  }
  // which observation-type polarities do the work
  for (const k of Object.keys(reg)) for (const o of reg[k]) types.add(o.replace(/^no_/, ''));
  return { n, types: [...types] };
}
const A = countSeparable(regA), B = countSeparable(regB), Bp = countSeparable(regBp);
check('28 family pairs', FAM.length * (FAM.length - 1) / 2 === 28);
check('regime A (taxonomy tags): 0 of 28 pairs core-separable', A.n === 0, `${A.n}/28`);
check('regime B (strongest testable reading): 9 of 28 pairs separable', B.n === 9, `${B.n}/28`);
check('regime B\' (theism permits but does not entail intervention): 6 of 28',
  Bp.n === 6, `${Bp.n}/28`);
check('every separable pair reduces to ONE observation type (interruption)',
  B.types.length === 1, B.types.join(', '));
check('the single discriminating type is the contested one (ledger rows 4/5)',
  B.types[0] === 'law_violating_interruption');

/* ------------------------------------------------------------------ *
 * 5. NEW (Part 9, C3): Duhem-Quine neutrality of a refuted conjunction
 * ------------------------------------------------------------------ */
console.log('\n[5] Duhem neutrality enumeration (new)');
// Prediction P true iff C and every auxiliary is true. Observe NOT-P.
// Under H_core (C is the false conjunct) and H_i (auxiliary i is the false
// conjunct), P(¬P | H) = 1 in every case: refutation is evidentially neutral.
// Fault probability is therefore P(H) / sum(P(H)) over fault sites.
function faultShare(wCore, wAux, k) { return wCore / (wCore + k * wAux); }
check('k=1 auxiliary, equal weights: core carries 1/2 of fault', approx(faultShare(1, 1, 1), 0.5));
check('k=3 auxiliaries, equal weights: core carries 1/4', approx(faultShare(1, 1, 3), 0.25));
check('k=3 auxiliaries, core weighted 5x: core carries 5/8 (prior does the work)',
  approx(faultShare(5, 1, 3), 0.625));
check('the SAME observation yields 0.25 or 0.625 purely from the prior',
  faultShare(1, 1, 3) !== faultShare(5, 1, 3));
// brute-force confirmation of the neutrality claim over all assignments
let neutralOk = true;
for (const k of [1, 2, 3, 4, 5, 6]) {
  for (let mask = 0; mask < (1 << (k + 1)); mask++) {
    // bit 0 = core truth; bits 1..k = auxiliaries
    const allTrue = mask === (1 << (k + 1)) - 1;
    const P = allTrue;                        // prediction holds iff all true
    const negP = !P;
    if (!negP) continue;                      // only refuted cases
    // every fault site (a false conjunct) must imply ¬P with probability 1
    if (mask === (1 << (k + 1)) - 1) continue;
    // count false conjuncts
    let falseConj = 0;
    for (let b = 0; b <= k; b++) if (!((mask >> b) & 1)) falseConj++;
    if (falseConj === 0) neutralOk = false;   // ¬P with no false conjunct => not neutral
  }
}
check('exhaustive enumeration: ¬P always has >=1 false conjunct (neutrality holds)', neutralOk);
// and: the core is a false conjunct in a strict minority of refuted worlds
for (const k of [1, 2, 3, 4, 5, 6]) {
  let refuted = 0, coreFalse = 0;
  for (let mask = 0; mask < (1 << (k + 1)); mask++) {
    const allTrue = mask === (1 << (k + 1)) - 1;
    if (allTrue) continue;
    refuted++;
    if (!((mask >> 0) & 1)) coreFalse++;
  }
  const share = coreFalse / refuted;
  check(`k=${k}: core is the false conjunct in 1/(k+1) = ${(1 / (k + 1)).toFixed(4)} of refuted worlds`,
    approx(share, 1 / (k + 1)), share.toFixed(4));
}

/* ------------------------------------------------------------------ *
 * 6. Protocol + tally consistency across both artifacts
 * ------------------------------------------------------------------ */
console.log('\n[6] protocol checks');
const banned = [/therefore god exists/gi, /therefore god does not exist/gi];
for (const [label, text] of [['taxonomy', taxonomy], ['new', newArt]]) {
  if (!text) continue;
  let hits = 0;
  for (const re of banned) { re.lastIndex = 0; const m = text.match(re); if (m) hits += m.length; }
  check(`${label}: 0 banned constructions`, hits === 0, hits ? String(hits) : '0');
}
check('taxonomy still reports 0 verdicts asserted', /Verdicts asserted on the existence[^|]*\|\s*\*\*0\*\*/.test(taxonomy));
check('new artifact carries the protocol note', /not empirically decidable|metaphysical/i.test(newArt));
check('new artifact reports 0/28 and 9/28', /0 of 28/.test(newArt) && /9 of 28/.test(newArt));
check('new artifact states the single discriminating observation type', /law-violating interruption/i.test(newArt));

/* ------------------------------------------------------------------ *
 * summary
 * ------------------------------------------------------------------ */
console.log(`\n==== ${pass} passed, ${fail} failed ====`);
if (fail) { console.log('FAILURES: ' + failures.join('; ')); process.exit(1); }
console.log('All checks green.');

