  const g = gate2(k);
  ok('gate-2 LR = 1.0 exactly at k=' + k, g.lrOk);
  ok('uniform-site share = 1/(k+1) at k=' + k, close(g.uniformSite, 1 / (k + 1), tolAbs));
}
