ok('C3 cross-check: uniform-world k=1 = 0.667', close(gate2(1).uniformWorld, 2 / 3, 1e-3));
ok('C3 cross-check: uniform-world k=3 = 0.5333', close(gate2(3).uniformWorld, 8 / 15, 1e-4));
